// index.js
import React from 'react';
import { render } from 'react-dom';
import { Form, TileGroup, RadioTile, Button } from 'carbon-components-react';
import 'carbon-components/css/carbon-components.min.css';
import './index.css';

function App() {
  function onSubmit(e) {
    // prevent React from taking over; let browser show validation UI
    e.preventDefault();
    // in a real form you would not preventDefault here
  }

  return (
    <div style={{ padding: '2rem' }}>
      <Form onSubmit={onSubmit}>
        <TileGroup legend="Choose an option" name="tiles">
          <RadioTile value="one" required>
            Tile 1
          </RadioTile>
          <RadioTile value="two" required>
            Tile 2
          </RadioTile>
          <RadioTile value="three" required>
            Tile 3
          </RadioTile>
        </TileGroup>
        <Button type="submit">Submit</Button>
      </Form>
    </div>
  );
}

render(<App />, document.getElementById('root'));

